1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
6	
7	/**
8	 * Runs after {@link ValidateOwnerFields} and before {@link BuildOwner} in the create-owner
9	 * pipeline. Normalizes the telephone into E.164 form and mutates the validated body in place so
10	 * later steps build, compare and store the normalized value.
11	 *
12	 * <p>Rules: strip spaces, dashes and brackets. A leading {@code '+'} keeps its country code as
13	 * given; otherwise country code {@code '+61'} is assumed and a single leading {@code '0'} is
14	 * dropped from the national digits. The result must be 8 to 15 digits after the {@code '+'};
15	 * anything else (or any leftover non-digit) is rejected with a 400. So {@code '0412 345 678'} is
16	 * stored as {@code '+61412345678'}.
17	 */
18	public class NormalizeOwnerTelephone {
19	
20	    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
21	        String raw = request.getTelephone();
22	        request.setTelephone(toE164(raw));
23	    }
24	
25	    private static String toE164(String raw) throws InvalidTelephoneException {
26	        if (raw == null) {
27	            throw new InvalidTelephoneException(raw);
28	        }
29	        String trimmed = raw.trim();
30	        boolean hasCountryCode = trimmed.startsWith("+");
31	        // Strip formatting: spaces, dashes and brackets.
32	        String cleaned = trimmed.replaceAll("[\\s\\-()]", "");
33	
34	        String digits;
35	        if (hasCountryCode) {
36	            digits = cleaned.substring(1); // drop the leading '+', keep the country code
37	        } else {
38	            String national = cleaned;
39	            if (national.startsWith("0")) {
40	                national = national.substring(1); // drop a single leading national-trunk '0'
41	            }
42	            digits = "61" + national; // assume Australian country code
43	        }
44	
45	        if (!digits.matches("\\d{8,15}")) {
46	            throw new InvalidTelephoneException(raw);
47	        }
48	        return "+" + digits;
49	    }
50	}
