3	import java.util.regex.Pattern;
4	
5	import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
6	
7	/**
8	 * Shared email handling for the owner pipeline. Not an OfficeFloor function class (it is never
9	 * referenced from a step), so it may expose helper methods.
10	 */
11	final class OwnerEmails {
12	
13	    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
14	
15	    private OwnerEmails() {
16	    }
17	
18	    /**
19	     * Returns the email lower-cased, or the original value unchanged when absent (null or blank).
20	     * Throws when a present value is not a syntactically valid address.
21	     */
22	    static String normalize(String email) throws InvalidEmailException {
23	        if (email == null || email.isBlank()) {
24	            return email;
25	        }
26	        if (!EMAIL.matcher(email).matches()) {
27	            throw new InvalidEmailException(email);
28	        }
29	        return email.toLowerCase();
30	    }
31	}
